(window.CARDS = window.CARDS || {}).profession = [{"name":"Космонавт","emoji":"🚀","meta":["космонавтика","космические полёты","орбитальная станция"],"description":"Управляет космическим кораблём и проводит научные эксперименты в невесомости, живя неделями или месяцами на орбитальной станции. Перед полётом проходит долгие тренировки, изучает системы корабля, медицину и работу в скафандре.","fact":"Перед стартом с Байконура российские космонавты по традиции смотрят фильм «Белое солнце пустыни».","wiki_en":"Astronaut"},{"name":"Пилот","emoji":"✈️","meta":["авиация","управляет самолётом","кабина воздушного судна"],"description":"Управляет самолётом вместе со вторым пилотом, следит за приборами и постоянно на связи с диспетчерами на земле. Проходит регулярные медосмотры и тренировки на тренажёрах, чтобы быть готовым к любой нештатной ситуации.","fact":"Перед каждым полётом пилоты обязаны пройти инструктаж и проверить самолёт по строгому чек-листу.","wiki_en":"Aircraft pilot"},{"name":"Хирург","emoji":"🔪","meta":["медицина","делает операции","операционная"],"description":"Проводит операции на органах и тканях, устраняя травмы, опухоли и врождённые пороки, которые нельзя вылечить лекарствами. Работает в стерильной операционной вместе с анестезиологом и ассистентами, иногда по много часов подряд.","fact":"Перед операцией хирурги проходят строгую многоступенчатую обработку рук и надевают стерильные перчатки и халат.","wiki_en":"Surgeon"},{"name":"Стоматолог","emoji":"🦷","meta":["медицина","лечит зубы","стоматологический кабинет"],"description":"Лечит зубы и дёсны, ставит пломбы, коронки и брекеты, а также следит за здоровьем всей полости рта. На приёме использует бормашину, зеркало и множество мелких инструментов для точной работы в тесном пространстве.","fact":"Боязнь стоматолога — одна из самых распространённых фобий в мире, у неё есть отдельное название — дентофобия.","wiki_en":"Dentist"},{"name":"Ветеринар","emoji":"🐾","meta":["медицина","лечит животных","ветклиника"],"description":"Лечит домашних и сельскохозяйственных животных, ставит диагнозы без слов от пациента и оперирует питомцев любых размеров — от хомяка до лошади. Также делает прививки и следит за здоровьем животных на фермах и в зоопарках.","fact":"Многие ветеринары специализируются на одном виде животных, например только на птицах, рептилиях или лошадях.","wiki_en":"Veterinarian"},{"name":"Пожарный","emoji":"🧯","meta":["спасение людей","тушит пожары","пожарная часть"],"description":"Тушит пожары и спасает людей из огня, дыма и завалов, а ещё выезжает на аварии, наводнения и другие чрезвычайные ситуации. Работает в тяжёлом снаряжении и дыхательном аппарате, часто в условиях высокой температуры и плохой видимости.","fact":"Пожарные проверяют исправность техники и снаряжения в начале каждой смены, чтобы быть готовыми выехать за считаные минуты.","wiki_en":"Firefighter"},{"name":"Полицейский","emoji":"👮","meta":["правопорядок","охраняет порядок","улицы и участок"],"description":"Следит за соблюдением законов, патрулирует улицы, разбирает конфликты и расследует правонарушения. Работает в форме и на виду у людей, поэтому должен сочетать твёрдость с умением договариваться в стрессовых ситуациях.","fact":"В разных странах у полицейских разная форма и полномочия — где-то они по умолчанию несут службу без огнестрельного оружия.","wiki_en":"Police officer"},{"name":"Частный детектив","emoji":"🕵️","meta":["частный сыск","ведёт расследования","на заказ, в разъездах"],"description":"Собирает информацию и ведёт расследования по заказу частных лиц или компаний — от поиска пропавших людей до проверки неверности супругов и корпоративного мошенничества. В отличие от полиции действует в рамках гражданских, а не уголовных полномочий.","fact":"Образ детектива с трубкой и лупой во многом создан литературой — реальная работа чаще состоит из архивов и слежки.","wiki_en":"Private investigator"},{"name":"Судья","emoji":"🧑‍⚖️","meta":["правосудие","выносит решения","зал суда"],"description":"Рассматривает дела в суде и выносит решения на основе законов и представленных сторонами доказательств. Должен сохранять беспристрастность и обосновывать каждый приговор или постановление ссылками на конкретные нормы права.","fact":"В некоторых странах судьи носят особые мантии и парики — эта традиция восходит к британским судам XVII века.","wiki_en":"Judge"},{"name":"Адвокат","emoji":"⚖️","meta":["право","защищает клиента","суд и юридическая контора"],"description":"Защищает интересы клиента в суде и вне его — составляет договоры, даёт юридические консультации и выстраивает линию защиты или обвинения. Должен хорошо знать законы и уметь убедительно аргументировать позицию перед судьёй и присяжными.","fact":"Адвокатская тайна означает, что адвокат не может раскрыть информацию, полученную от клиента, даже по требованию следствия.","wiki_en":"Lawyer"},{"name":"Шеф-повар","emoji":"👨‍🍳","meta":["кулинария","руководит кухней","ресторанная кухня"],"description":"Руководит кухней ресторана, придумывает меню и следит, чтобы каждое блюдо выходило одинаково идеальным. Помимо готовки отвечает за закупки продуктов, обучение поваров и порядок на кухне во время самого напряжённого сервиса.","fact":"Высокий белый колпак шеф-повара называют токе, и по традиции его высота указывала на положение повара в кухонной иерархии.","wiki_en":"Chef"},{"name":"Бармен","emoji":"🍸","meta":["общепит","готовит напитки","бар"],"description":"Смешивает коктейли, наливает напитки и создаёт атмосферу за барной стойкой, часто становясь для посетителей кем-то средним между собеседником и психологом. Должен помнить десятки рецептов и уметь работать быстро в вечерний наплыв гостей.","fact":"Искусство эффектно подбрасывать и крутить шейкеры и бутылки называют флейрингом, от английского flair.","wiki_en":"Bartender"},{"name":"Сомелье","emoji":"🍷","meta":["общепит","дегустирует вино","ресторан, винотека"],"description":"Подбирает вино к блюдам, консультирует гостей ресторана и следит за винной картой и условиями хранения бутылок. Умеет по запаху и вкусу определить сорт винограда, регион и примерный год урожая, не глядя на этикетку.","fact":"Само слово пришло из французского, где так когда-то называли слугу, отвечавшего за припасы и напитки в доме господина.","wiki_en":"Sommelier"},{"name":"Бариста","emoji":"☕","meta":["общепит","готовит кофе","кофейня"],"description":"Готовит кофе на профессиональной кофемашине, настраивает помол и температуру под каждый сорт зерна и рисует латте-арт на молочной пене. Хороший бариста разбирается не только в эспрессо, но и в альтернативных способах заварки.","fact":"Чемпионаты мира по бариста-мастерству судят не только по вкусу напитка, но и по технике приготовления и подаче.","wiki_en":"Barista"},{"name":"Кондитер","emoji":"🍰","meta":["кулинария","печёт десерты","кондитерский цех"],"description":"Создаёт торты, пирожные и другие десерты, сочетая точную рецептуру с художественным оформлением. Работает с шоколадом, кремом и мастикой, а для сложных свадебных тортов иногда собирает многоярусные конструкции вручную.","fact":"Профессиональные кондитеры взвешивают почти все ингредиенты на весах, а не измеряют стаканами и ложками, ради точности.","wiki_en":"Pastry chef"},{"name":"Пекарь","emoji":"🍞","meta":["пищевое производство","печёт хлеб","пекарня"],"description":"Замешивает тесто и выпекает хлеб и другую сдобу, начиная работу зачастую глубокой ночью, чтобы к утру на прилавках была свежая выпечка. Следит за температурой и влажностью в печи и за тем, как ведёт себя дрожжевое тесто на каждом этапе.","fact":"Традиция печь хлеб на закваске без дрожжей насчитывает тысячи лет и до сих пор жива во многих пекарнях.","wiki_en":"Baker"},{"name":"Фермер","emoji":"🚜","meta":["сельское хозяйство","выращивает урожай","поле и ферма"],"description":"Выращивает зерновые культуры, овощи или разводит скот, обеспечивая продуктами города и рынки. Работа зависит от сезона и погоды, а современный фермер часто совмещает физический труд с управлением техникой и финансами хозяйства.","fact":"Урожайность и погода делают труд фермера одним из самых непредсказуемых — многое зависит от факторов, которые невозможно контролировать.","wiki_en":"Farmer"},{"name":"Рыбак","emoji":"🎣","meta":["промысел","ловит рыбу","море, река, судно"],"description":"Ловит рыбу и морепродукты сетями, неводами или удочками, работая на промысловых судах или у берега. Профессиональный рыбак должен разбираться в повадках рыбы, сезонных миграциях и правилах, ограничивающих вылов в разных водах.","fact":"Промысловый вылов рыбы в открытом море считается одним из самых опасных занятий из-за штормов и удалённости от помощи.","wiki_en":"Fisherman"},{"name":"Шахтёр","emoji":"⛏️","meta":["добыча ископаемых","добывает ископаемые","подземная шахта"],"description":"Добывает уголь, руду и другие полезные ископаемые глубоко под землёй, где работает в темноте, тесноте и при постоянном риске обвалов и загазованности. Использует спецтехнику и системы вентиляции, но труд остаётся одним из самых тяжёлых физически.","fact":"Раньше шахтёры брали в забой канарейку: птица реагировала на опасный газ раньше людей, а сегодня её заменили газоанализаторы.","wiki_en":"Miner"},{"name":"Сварщик","emoji":"🔥","meta":["промышленность","сваривает металл","цех, стройка"],"description":"Соединяет металлические детали с помощью сварочного аппарата, расплавляя кромки и создавая прочный шов. Работает в защитной маске от яркой вспышки дуги и искр, а хороший сварщик умеет держать шов ровным даже в неудобном положении.","fact":"Яркий свет сварочной дуги и её ультрафиолетовое излучение без маски способны обжечь глаза — это называют «зайчиками» сварщика.","wiki_en":"Welder"},{"name":"Электрик","emoji":"🔌","meta":["строительство и быт","монтирует электросети","дома, объекты"],"description":"Прокладывает электропроводку, устанавливает розетки, щитки и освещение, а также устраняет неполадки в электросетях домов и предприятий. Работа требует строгого соблюдения техники безопасности, ведь ошибка может привести к удару током или пожару.","fact":"Перед началом работ электрик обязательно проверяет отсутствие напряжения в цепи специальным индикатором, даже если сеть должна быть отключена.","wiki_en":"Electrician"},{"name":"Сантехник","emoji":"🚰","meta":["строительство и быт","чинит сантехнику","дома, квартиры"],"description":"Устанавливает и ремонтирует трубы, краны, унитазы и системы отопления, устраняя протечки и засоры. Часто работает в стеснённых условиях — под раковиной или в тесном техническом помещении — и должен быстро находить источник проблемы.","fact":"Английское слово plumber восходит к латинскому plumbum — «свинец»: в Древнем Риме водопроводные трубы делали именно из него.","wiki_en":"Plumber"},{"name":"Строитель","emoji":"👷","meta":["строительство","возводит здания","стройплощадка"],"description":"Возводит дома, дороги и другие объекты, работая с бетоном, кирпичом и арматурой на разных этапах стройки. Профессия объединяет множество узких специальностей — от каменщика до крановщика — под общим руководством прораба.","fact":"Каска на стройке обязательна не для красоты — падение даже небольшого предмета с высоты способно привести к серьёзной травме.","wiki_en":"Construction worker"},{"name":"Архитектор","emoji":"📐","meta":["строительство","проектирует здания","архитектурное бюро"],"description":"Проектирует здания и городские пространства, сочетая инженерные расчёты с эстетикой и удобством для людей. Работает над чертежами и 3D-моделями, а затем сопровождает объект на стройке, следя за соответствием проекту.","fact":"Строительство Сиднейского оперного театра растянулось на годы дольше и обошлось дороже, чем закладывалось в изначальном проекте.","wiki_en":"Architect"},{"name":"Инженер","emoji":"⚙️","meta":["техника","проектирует и рассчитывает","завод, бюро"],"description":"Разрабатывает и рассчитывает технические системы — от мостов до двигателей, применяя законы физики и математики для решения практических задач. Специализаций у инженера множество: от строительной до космической и программной техники.","fact":"Слово «инженер» восходит к латинскому ingenium — «природный ум, изобретательность», а так когда-то называли создателей осадных машин.","wiki_en":"Engineer"},{"name":"Программист","emoji":"💻","meta":["IT","пишет программный код","за компьютером, удалённо"],"description":"Пишет код для сайтов, приложений и других программ, превращая задачи бизнеса в работающие алгоритмы. Много времени уходит не только на написание кода, но и на поиск и исправление ошибок — их называют багами.","fact":"Знаменитая запись о «первом настоящем баге» появилась в 1947 году, когда в реле компьютера Harvard Mark II нашли застрявшего мотылька.","wiki_en":"Programmer"},{"name":"Специалист по кибербезопасности","emoji":"🛡️","meta":["IT","защищает данные","IT-отдел компании"],"description":"Защищает компьютерные системы и данные компаний от взломов, вирусов и утечек, выявляя уязвимости раньше злоумышленников. Часть специалистов работает на стороне защиты, а часть — этичными хакерами, которые по заказу компании ищут дыры в системе.","fact":"Легальный поиск уязвимостей за вознаграждение от компаний называют bug bounty — «охотой за багами».","wiki_en":"Computer security"},{"name":"Дизайнер","emoji":"🎨","meta":["творчество","создаёт визуальные образы","студия, удалённо"],"description":"Создаёт визуальный облик продуктов, сайтов, упаковки или интерьеров, сочетая эстетику с удобством использования. Работает с цветом, шрифтами и композицией, а решения часто обосновывает не только вкусом, но и исследованиями пользователей.","fact":"Направление, отвечающее за удобство и логику интерфейсов, а не только их внешний вид, называют UX-дизайном.","wiki_en":"Designer"},{"name":"Тату-мастер","emoji":"✒️","meta":["творчество","делает татуировки","тату-салон"],"description":"Наносит несмываемые рисунки на кожу с помощью тату-машинки, вводящей чернила под верхний слой кожи. Перед сеансом обсуждает с клиентом эскиз и место нанесения, а после — как ухаживать за свежей татуировкой во время заживления.","fact":"Одни из древнейших известных татуировок — на теле ледяной мумии Этци, человека, жившего более пяти тысяч лет назад.","wiki_en":"Tattoo artist"},{"name":"Парикмахер","emoji":"✂️","meta":["красота","стрижёт волосы","парикмахерская, салон"],"description":"Стрижёт, укладывает и окрашивает волосы, а также ухаживает за причёской клиента, подбирая образ под форму лица и пожелания. Помимо техники стрижки важно умение слушать клиента и держать разговор во время долгого сеанса.","fact":"В старину цирюльники совмещали стрижку с удалением зубов и небольшими хирургическими операциями — отсюда красно-белый столб у парикмахерских.","wiki_en":"Hairdresser"},{"name":"Визажист","emoji":"💄","meta":["красота","наносит макияж","салон, съёмки, свадьбы"],"description":"Создаёт макияж для повседневных образов, съёмок и торжественных событий, подбирая цвета и техники под тип кожи и черты лица клиента. Часто работает в паре с фотографом или стилистом на модных показах и киносъёмках.","fact":"На кинопроизводстве визажисты нередко создают не только красивый, но и «возрастной» или боевой грим с помощью силиконовых накладок.","wiki_en":"Make-up artist"},{"name":"Модель","emoji":"👗","meta":["мода","демонстрирует одежду","подиум, съёмки"],"description":"Демонстрирует одежду и образы на подиумах показов мод, в рекламе и на фотосъёмках для журналов и брендов. Работа требует не только внешних данных, но и умения держать осанку, менять выражение лица и подстраиваться под образ за считаные минуты.","fact":"Модельный кастинг часто включает просмотр портфолио — подборки лучших фотографий модели в разных образах и стилях.","wiki_en":"Model (person)"},{"name":"Актёр","emoji":"🎭","meta":["искусство","играет роли","театр, кино, сериалы"],"description":"Играет роли в театре, кино и сериалах, перевоплощаясь в разных персонажей и передавая их эмоции зрителю. Готовится к роли через разбор сценария, репетиции и иногда серьёзное изменение внешности или манеры речи.","fact":"Театральному актёру приходится держать роль в памяти целиком: дублей, как в кино, на сцене не бывает.","wiki_en":"Actor"},{"name":"Кинорежиссёр","emoji":"🎬","meta":["искусство","руководит съёмками фильма","съёмочная площадка"],"description":"Руководит съёмками фильма, формируя его художественное видение — от работы с актёрами до выбора кадра, света и монтажа. Превращает сценарий в готовую историю на экране, координируя работу десятков людей на площадке.","fact":"Согласно одной из версий, команда «Мотор!» восходит к тем временам, когда кинокамеру запускали механическим приводом.","wiki_en":"Film director"},{"name":"Каскадёр","emoji":"🤸","meta":["кино","выполняет трюки","съёмочная площадка"],"description":"Выполняет опасные трюки в кино вместо актёров — драки, падения, автомобильные погони и пожары, — тщательно репетируя каждое движение ради безопасности. Использует страховку, маты и защитную экипировку, скрытую от камеры.","fact":"Некоторые каскадёры специализируются только на одном виде трюков, например на огненных или автомобильных, годами оттачивая именно его.","wiki_en":"Stunt performer"},{"name":"Фотограф","emoji":"📷","meta":["творчество","снимает фотографии","студия, на выезде"],"description":"Снимает людей, события и предметы, выстраивая композицию, свет и момент так, чтобы кадр рассказывал историю. Работает как в студии с искусственным светом, так и на улице, подстраиваясь под естественное освещение и погоду.","fact":"До изобретения цифровых камер фотографы проявляли плёнку вручную в тёмной комнате, используя специальные химические растворы.","wiki_en":"Photographer"},{"name":"Журналист","emoji":"📰","meta":["медиа","собирает новости","редакция, на выезде"],"description":"Собирает информацию, берёт интервью и пишет материалы для газет, сайтов или телевидения, стараясь проверить факты из нескольких независимых источников. Часто работает в сжатые сроки, особенно если пишет о событии, происходящем прямо сейчас.","fact":"Правило проверять любой факт минимум по двум независимым источникам — один из базовых принципов журналистской этики.","wiki_en":"Journalist"},{"name":"Телеведущий","emoji":"🎙️","meta":["медиа","ведёт телепередачи","телестудия"],"description":"Ведёт телепередачи — новости, шоу или трансляции, — держа внимание зрителя голосом, темпом речи и умением импровизировать при технических накладках. Работает с суфлёром и сценарием, но должен уметь и отступить от него, если что-то пошло не так.","fact":"Текст на телесуфлёре бежит перед камерой так, что ведущий будто бы говорит без бумажки, глядя прямо в объектив.","wiki_en":"Television presenter"},{"name":"Блогер","emoji":"📱","meta":["медиа","создаёт контент","соцсети, дома"],"description":"Создаёт тексты, фото и видео для своей аудитории в социальных сетях на определённую тему — от путешествий до финансов. Помимо творческой части занимается монтажом, продвижением и общением с подписчиками, превращая это в постоянную работу.","fact":"Многие успешные блогеры начинали как любители и лишь со временем превратили хобби в основной источник дохода.","wiki_en":"Blog"},{"name":"Стример","emoji":"🎮","meta":["медиа","ведёт прямые трансляции","дома, студия"],"description":"Ведёт прямые трансляции — игры, разговоры или творческий процесс, — в реальном времени общаясь с зрителями в чате. Успех сильно зависит от регулярности эфиров и умения удерживать внимание аудитории часами подряд.","fact":"Донаты и подписки зрителей — один из основных способов заработка стримеров на таких платформах, как Twitch.","wiki_en":"Live streaming"},{"name":"Киберспортсмен","emoji":"🕹️","meta":["киберспорт","играет в видеоигры","студия, арена, турниры"],"description":"Профессионально соревнуется в видеоиграх в составе команды, часами отрабатывая реакцию и слаженные тактические связки на тренировках. Выступает на турнирах с призовым фондом, которые нередко транслируют в интернете для большой зрительской аудитории.","fact":"Крупнейшие киберспортивные турниры сегодня проходят на аренах перед живыми зрителями, как и обычные спортивные состязания.","wiki_en":"Esports"},{"name":"Диджей","emoji":"🎧","meta":["музыка","сводит и играет треки","клуб, вечеринка"],"description":"Подбирает и сводит треки в единый танцевальный сет, удерживая внимание зала сменой темпа и настроения. Работает с виниловыми пластинками, CD-проигрывателями или цифровыми плеерами, а хороший диджей чувствует публику лучше любого готового плейлиста.","fact":"Приём, при котором диджей вручную двигает пластинку под иглой для ритмичного звука, называют скретчингом.","wiki_en":"Disc jockey"},{"name":"Дирижёр","emoji":"🎼","meta":["музыка","руководит оркестром","концертный зал, театр"],"description":"Руководит оркестром или хором без единого произнесённого слова — только жестами рук и дирижёрской палочки задаёт темп, динамику и характер исполнения. Перед концертом проводит долгие репетиции, добиваясь слаженного звучания десятков музыкантов.","fact":"Дирижёр обычно стоит спиной к зрителям, потому что все его жесты обращены к оркестру, а не к публике.","wiki_en":"Conductor (music)"},{"name":"Балерина","emoji":"🩰","meta":["балет","танцует классический балет","театр, сцена"],"description":"Исполняет партии в классическом балете, годами тренируя растяжку, выносливость и умение подолгу танцевать на кончиках пальцев в пуантах. За плечами почти каждой балерины — ежедневные многочасовые тренировки у станка с раннего детства.","fact":"Пуанты — жёсткие балетные туфли — каждая балерина подгоняет под себя индивидуально, иногда специально разнашивая новую пару перед спектаклем.","wiki_en":"Ballet dancer"},{"name":"Клоун","emoji":"🤡","meta":["цирк и шоу","смешит публику","цирк, праздники"],"description":"Смешит публику при помощи трюков, пантомимы и нелепых ситуаций, часто без единого слова, полагаясь только на мимику и жесты. Работает в цирке, на детских праздниках и уличных представлениях, создавая яркий узнаваемый образ.","fact":"Грим клоуна считается его личным образом: многие артисты годами не меняют однажды придуманное лицо.","wiki_en":"Clown"},{"name":"Фокусник","emoji":"🎩","meta":["цирк и шоу","показывает иллюзии","сцена, шоу"],"description":"Показывает трюки с исчезновением предметов, картами и левитацией, создавая у зрителей ощущение настоящего чуда. За кажущейся магией стоят месяцы отработки ловкости рук, отвлечения внимания и точного расчёта времени каждого движения.","fact":"Среди фокусников не принято раскрывать секреты трюков коллег — это негласное правило бережно хранят десятилетиями.","wiki_en":"Magician (illusion)"},{"name":"Дрессировщик","emoji":"🦁","meta":["цирк и шоу","обучает животных","цирк, зоопарк"],"description":"Обучает животных выполнять команды и трюки, выстраивая доверие через терпение и постоянные тренировки. Работает с самыми разными видами — от собак и лошадей до хищников, — учитывая повадки и характер каждого отдельного животного.","fact":"Современные подходы к дрессуре всё чаще опираются на положительное подкрепление лакомством, а не на принуждение.","wiki_en":"Animal trainer"},{"name":"Писатель","emoji":"📖","meta":["литература","пишет книги","дома, за столом"],"description":"Сочиняет романы, рассказы или нон-фикшн, превращая идеи в связный текст, который держит внимание читателя от первой до последней страницы. Путь от замысла до готовой книги часто занимает месяцы или даже годы переписывания и правок.","fact":"Многие известные писатели строго придерживались собственного ежедневного ритуала письма, например работали только в одно и то же время суток.","wiki_en":"Writer"},{"name":"Переводчик","emoji":"🗣️","meta":["лингвистика","переводит тексты и речь","офис, кабина, удалённо"],"description":"Переводит устную речь или письменные тексты с одного языка на другой, стараясь точно передать не только слова, но и смысл, тон и культурный контекст. Синхронисты в кабине переводят речь докладчика почти без задержки, прямо во время выступления.","fact":"Синхронный перевод требует такой концентрации, что переводчики в кабине обычно сменяют друг друга каждые 20–30 минут.","wiki_en":"Translator"},{"name":"Учитель","emoji":"📚","meta":["образование","преподаёт школьникам","школа"],"description":"Преподаёт школьникам один или несколько предметов, готовит уроки и проверяет тетради, а заодно помогает детям найти интерес к учёбе. Кроме уроков занимается воспитательной работой, внеклассными занятиями и общением с родителями учеников.","fact":"В разных странах существуют собственные праздники в честь учителей — например, в России это 5 октября.","wiki_en":"Teacher"},{"name":"Профессор","emoji":"🎓","meta":["наука и образование","преподаёт и исследует","университет"],"description":"Преподаёт в университете и одновременно ведёт собственные научные исследования, публикуя статьи и руководя работами студентов и аспирантов. Профессорское звание обычно присваивают за многолетний признанный вклад в науку и преподавание.","fact":"В разных странах слово «профессор» означает разное: где-то это высшее учёное звание, а где-то — просто должность преподавателя университета.","wiki_en":"Professor"},{"name":"Библиотекарь","emoji":"📕","meta":["культура","систематизирует книги","библиотека"],"description":"Систематизирует книги и другие материалы, помогает посетителям найти нужное издание и ведёт учёт фонда библиотеки. Современный библиотекарь также занимается электронными каталогами и цифровыми архивами, а не только бумажными книгами.","fact":"Библиотечная классификация Дьюи, придуманная в XIX веке, до сих пор используется во многих библиотеках мира для расстановки книг по темам.","wiki_en":"Librarian"},{"name":"Археолог","emoji":"🏺","meta":["наука","изучает раскопки","экспедиции, музей"],"description":"Изучает быт древних людей по найденным при раскопках предметам, постройкам и захоронениям, восстанавливая картину прошлого по мельчайшим деталям. Работа сочетает полевые экспедиции с кропотливой лабораторной обработкой находок.","fact":"Гробницу Тутанхамона Говард Картер нашёл в 1922 году после нескольких лет безуспешных раскопок в Долине царей.","wiki_en":"Archaeologist"},{"name":"Палеонтолог","emoji":"🦴","meta":["наука","изучает ископаемые останки","экспедиции, музей"],"description":"Изучает ископаемые остатки динозавров и других древних организмов, чтобы восстановить, как выглядела жизнь на Земле миллионы лет назад. Находки часто представляют собой лишь фрагменты костей, по которым учёный воссоздаёт облик всего существа.","fact":"Многие скелеты динозавров в музеях частично состоят из гипсовых копий недостающих костей, дополняющих настоящие находки.","wiki_en":"Paleontology"},{"name":"Астроном","emoji":"🔭","meta":["наука","изучает космос","обсерватория"],"description":"Изучает звёзды, планеты и другие объекты Вселенной с помощью телескопов и данных космических миссий, пытаясь понять законы, по которым устроен космос. Часть работы проходит у телескопа ночью, но всё больше астрономов анализируют данные за компьютером.","fact":"Многие важные астрономические открытия делают не только профессионалы: любители с домашними телескопами регулярно находят новые кометы.","wiki_en":"Astronomer"},{"name":"Физик-ядерщик","emoji":"⚛️","meta":["наука","изучает атомное ядро","лаборатория, НИИ"],"description":"Изучает строение атомного ядра и процессы, происходящие при его делении или синтезе, — от этих знаний зависят и энергетика, и медицина. Работает в лабораториях и на крупных научных установках вроде ускорителей частиц.","fact":"Исследования в ядерной физике привели не только к атомной энергетике, но и к методам лучевой терапии в лечении онкологических заболеваний.","wiki_en":"Nuclear physics"},{"name":"Химик","emoji":"🧪","meta":["наука","изучает вещества и реакции","лаборатория, завод"],"description":"Изучает состав веществ и реакции между ними, создавая новые материалы, лекарства и технологии. Работает в лаборатории с реактивами и приборами, а часть химиков трудится на производстве, контролируя качество готовой продукции.","fact":"Периодическую таблицу химических элементов Дмитрий Менделеев составил так удачно, что она предсказала свойства ещё не открытых элементов.","wiki_en":"Chemist"},{"name":"Океанолог","emoji":"🌊","meta":["наука","изучает океан","экспедиции, судно"],"description":"Изучает течения, глубины и обитателей Мирового океана, объясняя, как океан влияет на климат всей планеты. Работа часто проходит в морских экспедициях на научных судах, а также с подводными аппаратами и буями с датчиками.","fact":"Дно океана исследовано куда хуже поверхности Луны — значительная его часть до сих пор не изучена и не нанесена на подробные карты.","wiki_en":"Oceanography"},{"name":"Вулканолог","emoji":"🌋","meta":["наука","изучает вулканы","экспедиции, действующий вулкан"],"description":"Изучает вулканы и старается предсказать извержения по составу газов, сейсмической активности и изменениям формы кратера. Ради образцов лавы и газа иногда приходится подходить к действующему кратеру в специальном термостойком костюме.","fact":"Некоторые вулканологи погибли во время наблюдений за извержениями — профессия остаётся одной из самых опасных в науке.","wiki_en":"Volcanology"},{"name":"Метеоролог","emoji":"🌦️","meta":["наука","прогнозирует погоду","метеостанция, офис"],"description":"Наблюдает за атмосферой и составляет прогнозы погоды, анализируя данные со спутников, радаров и метеостанций по всему миру. Помимо ежедневных прогнозов метеорологи предупреждают о надвигающихся ураганах, штормах и других опасных явлениях.","fact":"Первые регулярные метеосводки по телеграфу начали передавать ещё в XIX веке, что заложило основу современных служб погоды.","wiki_en":"Meteorologist"},{"name":"Геолог","emoji":"⛰️","meta":["наука","изучает горные породы","экспедиции, месторождения"],"description":"Изучает строение земной коры, горные породы и минералы, а также ищет месторождения полезных ископаемых. Много времени проводит в полевых экспедициях с молотком и компасом, читая историю Земли по слоям горных пород.","fact":"По слоям осадочных пород и составу минералов геологи способны восстановить события, произошедшие миллионы лет назад.","wiki_en":"Geologist"},{"name":"Психолог","emoji":"🧠","meta":["медицина","помогает с переживаниями","кабинет, консультации"],"description":"Помогает людям разобраться в переживаниях, отношениях и трудных решениях через беседу, без назначения лекарств — в отличие от психиатра. Работает с отдельными людьми, парами или группами, применяя разные терапевтические подходы.","fact":"Психолог и психиатр — разные профессии: психиатр имеет медицинское образование и может выписывать препараты, а психолог, как правило, нет.","wiki_en":"Psychologist"},{"name":"Фармацевт","emoji":"💊","meta":["медицина","отпускает лекарства","аптека"],"description":"Отпускает лекарства в аптеке, консультирует по дозировке и взаимодействию препаратов, а иногда сам изготавливает лекарственные формы. Хорошо знает химию и фармакологию, чтобы вовремя заметить опасное сочетание нескольких препаратов.","fact":"В старину аптекари сами готовили большинство лекарств вручную, смешивая порошки и настойки прямо за прилавком аптеки.","wiki_en":"Pharmacist"},{"name":"Медсестра","emoji":"💉","meta":["медицина","ухаживает за пациентами","больница, клиника"],"description":"Ухаживает за пациентами в больнице или клинике: делает уколы и перевязки, следит за состоянием и выполняет назначения врача. Часто именно медсестра проводит с пациентом больше времени, чем любой другой сотрудник больницы.","fact":"Флоренс Найтингейл, одна из основательниц современного сестринского дела, прославилась уходом за ранеными во время Крымской войны.","wiki_en":"Nursing"},{"name":"Фельдшер скорой помощи","emoji":"🚑","meta":["медицина","оказывает экстренную помощь","машина скорой помощи"],"description":"Оказывает экстренную медицинскую помощь на вызовах и по дороге в больницу, часто в первые и самые важные минуты после травмы или приступа. Должен быстро принимать решения в условиях стресса и ограниченного набора оборудования в салоне машины.","fact":"Медики скорой помощи используют понятие «золотой час» — первый час после тяжёлой травмы, когда своевременная помощь особенно повышает шансы на выживание.","wiki_en":"Emergency medical technician"},{"name":"Патологоанатом","emoji":"🔬","meta":["медицина","устанавливает причины смерти","морг, лаборатория"],"description":"Исследует ткани и органы, чтобы уточнить диагноз или установить причину смерти, работая на стыке медицины и криминалистики. Значительная часть работы связана не со вскрытиями, а с изучением тканей под микроскопом для диагностики живых пациентов.","fact":"Чтобы разглядеть ткань под микроскопом, из неё делают тончайший срез и окрашивают специальными красителями — иначе почти ничего не видно.","wiki_en":"Pathology"},{"name":"Акушер","emoji":"🤱","meta":["медицина","принимает роды","роддом"],"description":"Принимает роды и наблюдает за состоянием женщины и ребёнка на всех этапах беременности, а при осложнениях принимает решение о срочной помощи. Работа требует спокойствия и быстрой реакции, ведь роды не всегда проходят строго по плану.","fact":"В разных культурах веками существовали отдельные, обычно женские профессии повитух, которые помогали при родах без формального медицинского образования.","wiki_en":"Obstetrics"},{"name":"Футбольный тренер","emoji":"🧢","meta":["спорт","руководит командой","стадион, клуб"],"description":"Разрабатывает тактику матчей, тренирует игроков и принимает решения о составе и заменах прямо во время игры. Помимо футбольных знаний должен разбираться в психологии, чтобы держать команду мотивированной на протяжении всего сезона.","fact":"Некоторые тренеры выигрывали крупные турниры с разными клубами и сборными, доказывая, что тактическое мышление важнее состава одной конкретной команды.","wiki_en":"Manager (association football)"},{"name":"Футболист","emoji":"⚽","meta":["спорт","играет в футбол","стадион, клуб"],"description":"Играет в футбол за клуб или сборную, годами оттачивая технику владения мячом, скорость и тактическое мышление на поле. Профессиональная карьера обычно начинается ещё в детской футбольной академии и требует постоянных тренировок.","fact":"Футбол называют самым популярным видом спорта в мире — в него так или иначе играют в большинстве стран.","wiki_en":"Football player"},{"name":"Боксёр","emoji":"🥊","meta":["спорт","занимается боксом","ринг, зал"],"description":"Дерётся на ринге по строгим правилам, используя только удары руками, а победу приносят нокаут или решение судей по очкам. Подготовка к бою включает месяцы тренировок на выносливость, скорость реакции и отработку защиты.","fact":"Вес боксёров строго делится на весовые категории, чтобы соперники перед боем были примерно равны по массе тела.","wiki_en":"Boxing"},{"name":"Гонщик «Формулы-1»","emoji":"🏎️","meta":["автоспорт","пилотирует болид","гоночная трасса"],"description":"Пилотирует болид «Формулы-1» на очень высоких скоростях, выдерживая огромные физические перегрузки в скоростных поворотах. Помимо реакции и выносливости гонщику важно тонко чувствовать машину и постоянно держать связь с командой по рации.","fact":"Из-за жары в кабине и перегрузок во время гонки пилоты «Формулы-1» заметно теряют в весе за счёт потоотделения.","wiki_en":"Formula One"},{"name":"Альпинист","emoji":"🧗","meta":["спорт","восходит на горные вершины","горы, экспедиции"],"description":"Поднимается на горные вершины, включая самые высокие в мире, преодолевая разреженный воздух, холод и лавинную опасность. Восхождение на серьёзные вершины обычно занимает не один день и требует акклиматизации и снаряжения для экстремальных условий.","fact":"На больших высотах воздух настолько разрежен, что альпинисты на вершинах вроде Эвереста часто используют кислородные баллоны.","wiki_en":"Mountaineering"},{"name":"Водолаз","emoji":"🤿","meta":["спасение и работы","работает под водой","море, реки, объекты"],"description":"Выполняет работы под водой — от осмотра корпусов судов и подводных сооружений до поисково-спасательных операций. Использует специальное снаряжение с подачей воздуха и должен разбираться в физиологии погружений, чтобы избежать декомпрессионной болезни.","fact":"На больших глубинах дышат не обычным воздухом, а смесями с гелием — иначе азот под давлением вызывает состояние, похожее на опьянение.","wiki_en":"Professional diving"},{"name":"Спасатель","emoji":"🛟","meta":["спасение людей","спасает в чрезвычайных ситуациях","пляж, горы, завалы"],"description":"Спасает людей при пожарах, наводнениях, обвалах и других чрезвычайных ситуациях, часто первым прибывая на место происшествия. Работа требует физической подготовки, умения быстро оценить обстановку и владения разным спасательным снаряжением.","fact":"Работа спасателя нередко проходит в условиях, которые считаются небезопасными даже для специально обученных профессионалов.","wiki_en":"Rescue"},{"name":"Лесник","emoji":"🌲","meta":["лесное хозяйство","следит за лесом","лес, заповедник"],"description":"Следит за состоянием леса, борется с незаконной вырубкой и браконьерством, а также организует посадку молодых деревьев и профилактику пожаров. Работа проходит в основном на открытом воздухе, часто вдали от населённых пунктов.","fact":"В обязанности лесника нередко входит и учёт диких животных — сколько особей того или иного вида обитает на вверенном ему участке.","wiki_en":"Forester"},{"name":"Капитан корабля","emoji":"🚢","meta":["морское дело","командует судном","морское или речное судно"],"description":"Отвечает за судно и весь экипаж, принимает решения о курсе, погоде и безопасности плавания, неся полную ответственность за исход рейса. Путь до капитанского мостика обычно занимает годы работы на разных должностях на флоте.","fact":"По морской традиции капитан покидает тонущее судно последним, убедившись, что все остальные на борту благополучно эвакуированы.","wiki_en":"Sea captain"},{"name":"Машинист поезда","emoji":"🚆","meta":["железная дорога","управляет поездом","кабина локомотива"],"description":"Управляет поездом, следит за сигналами и состоянием пути, отвечая за безопасность сотен пассажиров одновременно. Работа требует высокой концентрации на протяжении всей смены, ведь тормозной путь тяжёлого состава может растянуться на сотни метров.","fact":"В кабине работает система контроля бдительности: машинист должен периодически подтверждать, что он в порядке, иначе поезд затормозит сам.","wiki_en":"Train driver"},{"name":"Дальнобойщик","emoji":"🚛","meta":["транспорт","перевозит грузы","трасса, фура"],"description":"Перевозит грузы на большие расстояния, проводя за рулём фуры долгие часы и дни, часто в других городах и странах. Работа требует выносливости и умения планировать маршрут с учётом обязательных остановок на отдых.","fact":"Во многих странах для дальнобойщиков законом ограничено время непрерывного вождения без отдыха ради безопасности на дороге.","wiki_en":"Truck driver"},{"name":"Таксист","emoji":"🚕","meta":["транспорт","перевозит пассажиров","город, автомобиль"],"description":"Перевозит пассажиров по городу на автомобиле, хорошо зная маршруты и умея быстро сориентироваться в пробках и объездах. С появлением навигаторов и приложений вызова такси профессия заметно изменилась, но умение общаться с пассажирами осталось важным.","fact":"В Лондоне водители знаменитых чёрных такси годами сдают экзамен «Знание», требующий выучить наизусть тысячи улиц города.","wiki_en":"Taxicab"},{"name":"Курьер","emoji":"📦","meta":["доставка","доставляет посылки","город, велосипед, машина"],"description":"Доставляет посылки, еду и документы адресатам, перемещаясь по городу пешком, на велосипеде, самокате или машине. С ростом онлайн-заказов и доставки еды профессия стала одной из самых массовых в крупных городах.","fact":"Курьеры на велосипедах и самокатах нередко успевают доставить заказ в плотном городском трафике быстрее, чем автомобиль.","wiki_en":"Courier"},{"name":"Авиадиспетчер","emoji":"🛫","meta":["авиация","управляет воздушным движением","диспетчерская вышка"],"description":"Следит за самолётами в небе и на земле, направляя их так, чтобы избежать столкновений и обеспечить безопасные взлёты и посадки. Работа требует постоянной концентрации: диспетчер одновременно держит в голове десятки бортов и их маршруты.","fact":"Авиадиспетчеры и пилоты общаются на специальном стандартизированном английском языке, чтобы избежать путаницы из-за акцента или терминов.","wiki_en":"Air traffic controller"},{"name":"Бортпроводник","emoji":"🧳","meta":["авиация","обслуживает пассажиров","салон самолёта"],"description":"Обеспечивает безопасность и комфорт пассажиров на борту — от инструктажа перед взлётом до помощи в экстренной ситуации. Помимо сервиса должен уметь оказать первую помощь и организовать эвакуацию пассажиров, если что-то пойдёт не так.","fact":"Перед каждым рейсом бортпроводники проходят инструктаж и обязаны знать расположение всех аварийных выходов и оборудования наизусть.","wiki_en":"Flight attendant"},{"name":"Дипломат","emoji":"🤝","meta":["международные отношения","представляет страну","посольство, переговоры"],"description":"Представляет интересы своей страны за рубежом, ведёт переговоры и помогает урегулировать разногласия между государствами мирным путём. Работает в посольствах и консульствах, а значительная часть карьеры обычно проходит за границей.","fact":"Дипломатическая неприкосновенность защищает дипломатов от ареста и суда в стране пребывания — эта традиция известна ещё с древности.","wiki_en":"Diplomat"},{"name":"Разведчик","emoji":"🕶️","meta":["спецслужбы","добывает секретную информацию","за рубежом, под прикрытием"],"description":"Собирает и анализирует секретную информацию в интересах своей страны, нередко работая под легендой — вымышленной биографией и прикрытием. Из-за секретности профессии подробности реальной работы разведчиков обычно становятся известны лишь спустя десятилетия, если вообще становятся.","fact":"Большая часть работы разведки — это анализ открытых источников, а не эффектные тайные операции, какими их показывают в кино.","wiki_en":"Espionage"},{"name":"Сапёр","emoji":"💣","meta":["военное дело","обезвреживает взрывоопасные предметы","полигон, зона конфликта"],"description":"Обнаруживает и обезвреживает мины, снаряды и другие взрывоопасные предметы, работая с ювелирной точностью, где цена ошибки крайне высока. Помимо разминирования сапёры часто устанавливают заграждения и инженерные сооружения в военное время.","fact":"У сапёров есть выражение о том, что в этой профессии ошибаются лишь однажды — оно отражает крайнюю цену любой неточности.","wiki_en":"Explosive ordnance disposal"},{"name":"Банкир","emoji":"🏦","meta":["финансы","управляет банковскими операциями","банк"],"description":"Управляет финансовыми операциями банка — от выдачи кредитов и вкладов до крупных инвестиционных сделок для компаний. Профессия объединяет множество направлений, от работы с обычными клиентами в отделении до аналитики на уровне целых рынков.","fact":"Слово «банк» происходит от итальянского banco — скамьи или прилавка, за которым средневековые менялы вели свои расчёты.","wiki_en":"Bank"},{"name":"Трейдер","emoji":"📈","meta":["финансы","торгует на бирже","биржа, офис"],"description":"Покупает и продаёт акции, валюту или другие финансовые активы на бирже, стараясь заработать на разнице цен. Решения часто нужно принимать за секунды, поэтому трейдер должен быстро анализировать новости и графики котировок.","fact":"Сегодня значительную часть биржевых сделок совершают не люди, а автоматические алгоритмы за доли секунды.","wiki_en":"Trader (finance)"},{"name":"Бухгалтер","emoji":"🧮","meta":["финансы","ведёт учёт финансов","офис, компания"],"description":"Ведёт учёт доходов, расходов и налогов компании, следя, чтобы вся финансовая документация была в порядке и соответствовала закону. Точность и внимание к деталям в этой профессии особенно важны — ошибка в отчётности может обернуться крупным штрафом.","fact":"Двойная запись — метод учёта, при котором каждая операция отражается сразу в двух счетах, — известна ещё со времён итальянского Возрождения.","wiki_en":"Accountant"},{"name":"Риелтор","emoji":"🏠","meta":["недвижимость","помогает покупать и продавать жильё","офис, показы"],"description":"Помогает клиентам покупать, продавать и снимать недвижимость, разбираясь в ценах района, юридических тонкостях сделки и состоянии рынка. Хороший риелтор умеет находить подходящие варианты и вести переговоры между продавцом и покупателем.","fact":"При оценке жилья риелторы ориентируются не только на площадь и ремонт, но и на такие факторы, как вид из окна и этаж дома.","wiki_en":"Real estate broker"},{"name":"Предприниматель","emoji":"💼","meta":["бизнес","создаёт и развивает бизнес","офис, собственное дело"],"description":"Создаёт и развивает собственное дело, беря на себя финансовые риски в надежде на прибыль от нового продукта или услуги. Помимо идеи предпринимателю нужны навыки управления людьми и деньгами, а ещё умение перестроить план, когда что-то идёт не так.","fact":"Многие известные компании начинались с малого — например, буквально в гараже основателей, прежде чем вырасти в крупный бизнес.","wiki_en":"Entrepreneurship"},{"name":"Священник","emoji":"✝️","meta":["религия","проводит богослужения","храм, церковь, приход"],"description":"Проводит богослужения и религиозные обряды, а также духовно наставляет прихожан в вопросах веры и повседневной жизни. Помимо служб священник нередко занимается благотворительностью и поддержкой нуждающихся членов своей общины.","fact":"В разных христианских конфессиях существуют разные правила: например, в православии и католичестве по-разному решается вопрос о браке священников.","wiki_en":"Priest"},{"name":"Ювелир","emoji":"💍","meta":["ремесло","изготавливает украшения","мастерская, ювелирный дом"],"description":"Изготавливает и ремонтирует украшения из драгоценных металлов и камней, сочетая точность ремесленника с художественным вкусом. Работает с крошечными деталями под увеличением, а огранка камня требует особой точности и многолетнего опыта.","fact":"Огранка «бриллиант» с десятками граней рассчитана так, чтобы преломлять свет и создавать максимальный блеск камня.","wiki_en":"Jeweller"},{"name":"Кузнец","emoji":"🔨","meta":["ремесло","куёт металл","кузница"],"description":"Придаёт металлу форму при помощи нагрева в горне и ударов молотом по наковальне, изготавливая инструменты, изделия и украшения. Ремесло одно из древнейших в истории человечества и до сих пор востребовано — от художественной ковки до реставрации.","fact":"В старину кузнецов нередко считали немного колдунами — способность превращать бесформенный кусок металла в готовое изделие казалась почти магией.","wiki_en":"Blacksmith"},{"name":"Столяр","emoji":"🪚","meta":["ремесло","изготавливает изделия из дерева","мастерская"],"description":"Изготавливает мебель, окна, двери и другие изделия из дерева, работая с пилами, рубанками и другими инструментами. Хороший столяр разбирается в свойствах разных пород дерева и умеет соединять детали без единого гвоздя.","fact":"Некоторые традиционные деревянные соединения, например «ласточкин хвост», держат конструкцию прочно вообще без клея и гвоздей.","wiki_en":"Carpenter"},{"name":"Часовщик","emoji":"⌚","meta":["ремесло","ремонтирует часы","мастерская, ателье"],"description":"Собирает, настраивает и ремонтирует часы, работая с десятками крошечных деталей механизма под увеличительным стеклом. Профессия требует терпения и очень твёрдой руки, ведь ошибка на долю миллиметра может остановить весь механизм.","fact":"В сложных механических часах может быть несколько сотен крошечных деталей, и часовщик обязан знать назначение каждой из них.","wiki_en":"Watchmaker"},{"name":"Парфюмер","emoji":"🌸","meta":["ремесло","создаёт ароматы","лаборатория, парфюмерный дом"],"description":"Создаёт ароматы для духов, смешивая десятки натуральных и синтетических компонентов в точных пропорциях. Работа во многом строится на невероятно тренированном обонянии, способном различать и запоминать тысячи отдельных запахов.","fact":"Профессиональных парфюмеров с исключительным обонянием иногда называют «носом» — от французского le nez.","wiki_en":"Perfumer"},{"name":"Флорист","emoji":"💐","meta":["ремесло","составляет букеты","цветочный магазин"],"description":"Составляет букеты и цветочные композиции для праздников, свадеб и повседневных подарков, разбираясь в сочетаемости цветов и их уходе. Должен хорошо знать, какие цветы сохраняются дольше, а какие быстро вянут в срезанном виде.","fact":"Правильная профессиональная обрезка стебля под углом и в воде заметно продлевает жизнь срезанным цветам в букете.","wiki_en":"Florist"},{"name":"Пчеловод","emoji":"🐝","meta":["сельское хозяйство","разводит пчёл","пасека"],"description":"Разводит пчёл и следит за состоянием ульев, а также собирает мёд, воск и другие продукты пчеловодства. Работа требует спокойствия рядом с роем и хорошего знания повадок пчёл в разное время года.","fact":"Пчеловоды используют дымарь, чтобы окуривать улей дымом, — это успокаивает пчёл и снижает риск быть ужаленным при осмотре.","wiki_en":"Beekeeping"},{"name":"Дегустатор","emoji":"👅","meta":["пищевая индустрия","оценивает вкус продуктов","лаборатория, производство"],"description":"Профессионально пробует еду, напитки или сырьё, чтобы оценить их качество, вкус и соответствие стандартам производства. Работа строится на тренированных вкусовых рецепторах и обонянии, способных различать тончайшие оттенки вкуса и запаха.","fact":"Профессиональные дегустаторы нередко выплёвывают пробуемый продукт, а не проглатывают его, чтобы сохранить чувствительность вкуса на весь день.","wiki_en":"Sensory analysis"},{"name":"Экскурсовод","emoji":"🗺️","meta":["туризм","проводит экскурсии","музей, город"],"description":"Проводит экскурсии по городу, музею или историческому объекту, рассказывая занимательные факты и оживляя историю для туристов. Хороший экскурсовод умеет держать внимание группы и отвечать на неожиданные вопросы, не заглядывая в шпаргалку.","fact":"В ряде стран, например в Италии, официальным гидам нужно получить лицензию, сдав экзамен на знание истории и искусства.","wiki_en":"Tour guide"},{"name":"Крупье","emoji":"🎰","meta":["игорный бизнес","ведёт игру за столом","казино"],"description":"Ведёт азартную игру за столом в казино — раздаёт карты, крутит рулетку и следит, чтобы все правила соблюдались честно. Работа требует быстрого счёта в уме и невозмутимого выражения лица независимо от того, сколько выигрывает или проигрывает игрок.","fact":"За игровыми столами и за самими крупье постоянно следят камеры под потолком — в казино эту систему наблюдения называют «глаз в небе».","wiki_en":"Croupier"}];
